import { createBrowserClient } from '@supabase/ssr'

export function createClient() {
  return createBrowserClient(
    process.env.NUXT_PUBLIC_WEBENTIC_URL!,
    process.env.NUXT_PUBLIC_WEBENTIC_PUBLISHABLE_KEY!
  )
}

import { defineNuxtRouteMiddleware, navigateTo, useRequestEvent } from 'nuxt/app'

import { createWebenticServerClient } from '../webentic/client'

export default defineNuxtRouteMiddleware(async (to) => {
  const event = useRequestEvent()

  // create Webentic SSR client directly here
  const supabase = createWebenticServerClient(event)

  // check current user
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user && to.path !== '/login') {
    return navigateTo('/login')
  }
})

import { createError, defineEventHandler } from 'h3'

import { createWebenticServerClient } from '../webentic/client'

export default defineEventHandler(async (event) => {
  // Create Webentic SSR client
  const supabase = createWebenticServerClient(event)

  // Example: get user session
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    return { error: 'Not authenticated' }
  }

  // Fetch profile row
  const { data, error } = await supabase.from('profiles').select('*').eq('id', user.id).single()

  if (error) {
    throw createError({ statusCode: 500, statusMessage: error.message })
  }

  return { profile: data }
})

import { createServerClient } from '@supabase/ssr'
import { deleteCookie, EventHandlerRequest, getCookie, H3Event, setCookie } from 'h3'

export const createWebenticServerClient = (event: H3Event<EventHandlerRequest> | undefined) => {
  return createServerClient(
    process.env.NUXT_PUBLIC_WEBENTIC_URL!,
    process.env.NUXT_PUBLIC_WEBENTIC_PUBLISHABLE_KEY!,
    {
      cookies: {
        get: (key) => getCookie(event!, key),
        set: (key, value, options) => setCookie(event!, key, value, options),
        remove: (key, options) => deleteCookie(event!, key, options),
      },
    }
  )
}
